// 11 · The "Whole Person" Load Model: training is one slice of what an athlete carries.
// Composition: hook = small figure bottom-right in an empty field, one-line headline top-left;
// takeaway = line top-left, question flush right in the lower half; alignment = left.
// Batch 11-15 hooks: small-figure-field / single-word / assume-vs-measured / quote-right / question-only.
// Batch 11-15 takeaways: question-right / centered / question-only / split-columns / headline-rule-question.

// Illustrative stacked load over a 16-week semester (not data).
function bump(w, c, width, h) { const d = (w - c) / width; return Math.abs(d) < 1 ? h * 0.5 * (1 + Math.cos(Math.PI * d)) : 0; }
const training = () => 0.62;
const academics = w => 0.22 + bump(w, 8, 1.6, 0.62) + bump(w, 15.2, 1.7, 0.78);
const life = w => 0.2 + bump(w, 11.5, 1.4, 0.16);

module.exports = {
  num: 11,
  slug: "the-whole-person-load-model",
  title: "The \"Whole Person\" Load Model",
  category: "Cross-Functional Integration",
  palette: "baylor",
  hero: { layout: "stacked-area-total", concept: "Training, academic and life load stacked across one semester: training stays flat, yet the total spikes at midterms and finals" },
  compose: { hook: "small-figure-field", takeaway: "question-right", align: "left" },
  oneIdea: "An athlete carries one total load. Practice is only part of it, and the rest is on the academic calendar.",
  question: "Which exam weeks are on our training calendar this semester?",
  caveats: `Mann et al. is one Division I football team (n = 101) over one season, observational, and the outcome is "injury restriction", not diagnosed injury. Use the published abstract values: odds of an injury restriction in exam weeks were 1.78 times those in ordinary in-season weeks (p = 0.0088). The accepted manuscript in Eric's Zotero library prints p = 0.09 for that comparison; the published abstract reports p = 0.0088. If an athletic trainer pulls the manuscript, that is why the numbers differ. The same paper's results table reports an odds ratio of 3.19 for players who played regularly; that figure is not in the abstract, so it stays off the slides. Training camp still carried the highest odds overall (OR 3.65 vs ordinary weeks). Hamlin et al.'s odds ratios are per unit change in a wellness score, so don't turn them into "times more likely". The stacked chart on slide 3 is an illustrative shape, not anyone's data. The idea is association, not proof that exams cause injuries.`,
  sources: [
