// 12 · Shared Language Across Silos: one word, read three ways, is three different plans.
// Composition: hook = one word at 104pt with a narrow lead beneath; takeaway = line centered,
// question beneath; alignment = center (insight and takeaway centered).

module.exports = {
  num: 12,
  slug: "shared-language-across-silos",
  title: "Shared Language Across Silos",
  category: "Cross-Functional Integration",
  palette: "charcoal",
  hero: { layout: "one-word-three-readings", concept: "The word 'load' in the center with three published readings beneath it: a force in newtons, the training dose and response, and the IOC's broad load including travel and stress" },
  compose: { hook: "single-word", takeaway: "centered", align: "center" },
  oneIdea: "The same word can carry three plans. Name the thing you measured, not the label.",
  question: "Which word do we use across units without ever defining it?",
  caveats: `The three readings on slide 3 are published definitions, not quotes from Baylor units, and each is a fair reading in its own field. Don't present Staunton et al. as "the right definition"; their point is that scientists should use mechanical terms correctly, while coaching language has its own long use of the word. Tenan and Alejo is an editorial (opinion), not a study; it is used for its argument that joint work needs a shared language and shared data. Rimer et al. is a practitioner article from a Division I department. The "his load is high" example on slide 4 was written for this deck. There is no trial showing that a glossary reduces injuries; the claim is about clear communication, which is the subject of the coordination deck (14).`,
  sources: [
    { id: "staunton2022", cite: "Staunton CA, Abt G, Weaving D, Wundersitz DWT. Misuse of the term 'load' in sport and exercise science. J Sci Med Sport. 2022;25(5):439-444. doi:10.1016/j.jsams.2021.08.013", grade: "critical commentary", found: "external (cited across Zotero items, e.g. Clubb et al. 2023)", supports: "In mechanics, a load is a force and should carry the newton as its unit; terms like 'training load' borrow the word loosely." },
    { id: "impellizzeri2019", cite: "Impellizzeri FM, Marcora SM, Coutts AJ. Internal and external training load: 15 years on. Int J Sports Physiol Perform. 2019;14(2):270-273. doi:10.1123/ijspp.2018-0935", grade: "conceptual commentary", found: "external", supports: "Training load has two measurable parts: external load (the work prescribed and done) and internal load (the athlete's psychophysiological response)." },
    { id: "soligard2016", cite: "Soligard T, Schwellnus M, Alonso JM, et al. How much is too much? (Part 1) International Olympic Committee consensus statement on load in sport and risk of injury. Br J Sports Med. 2016;50(17):1030-1041. doi:10.1136/bjsports-2016-096581", grade: "consensus statement", found: "external (cited across Zotero items)", supports: "Load defined broadly: training and competition load, calendar congestion, psychological load and travel." },
    { id: "tenan2024", cite: "Tenan MS, Alejo B. Athlete health and human performance will not improve without transdisciplinary collaboration and data sharing in elite sport. J Athl Train. 2024;59(10):979-983. doi:10.4085/1062-6050-0580.23", grade: "editorial (expert opinion)", found: "Zotero", supports: "Transdisciplinary work needs all groups to 'speak the same language', share data and agree on a framework (p. 981)." },
    { id: "rimer2024", cite: "Rimer E, Petway A, Jones P, et al. Building comprehensive integration of health and performance support through sport science. Strength Cond J. 2024;46(1):55-68. doi:10.1519/SSC.0000000000000794", grade: "practitioner article", found: "Zotero", supports: "'Research has different meanings among different groups': academia, technology companies and athletic departments each read the word differently. Separate directors with different philosophies can preserve silos." },
  ],
  slides: [
    {
      role: "hook", time: 45,
      notes: `One word. Load.

Athletic Performance uses it every day. Athletic Medicine uses it. Our mental health staff talk about load, and academics talks about course load. Every unit in this room says it, and we nod at each other when we do.

Today's question is whether we mean the same thing when we say it. Mostly, we don't.`,
      build(s) {
        s.headline("Load.", { x: 0.75, y: 1.55, w: 6, h: 1.8, size: 104, color: "accent" });
        s.lead("Every unit in this room uses the word. We don't all mean the same thing by it.", { x: 0.75, y: 3.65, w: 6, h: 1.7, size: 24 });
      },
    },
    {
      role: "problem", time: 60,
      notes: `Here is why it matters. Say a coach hears "his load is high" in a staff meeting. Athletic Performance might mean his running volume jumped. Athletic Medicine might mean a tendon is taking more than it can handle. Academics might mean three exams this week. Same sentence, three different plans.

Each unit hears its own meaning and acts on it, and nobody notices the mismatch until later. A Division I group at Louisville made the same point about the word "research": academics, tech companies and athletic departments each read it differently. And a recent editorial in the Journal of Athletic Training argues that working across units starts with everyone speaking the same language.`,
      build(s) {
        s.headline("One word can hide three different plans.", { x: 0.75, y: 1.2, w: 11.5, h: 0.9, size: 44 });
        const rows = [
          "“Load is high” can mean more running, sore tissue or a hard week.",
          "Each unit hears its own meaning.",
          "Joint work needs everyone to “speak the same language.”",
        ];
        rows.forEach((t, i) => {
          const y = 2.55 + i * 1.2;
          s.line(0.75, y, 12.58, y, { color: "rule", w: 1 });
          s.text(0.75, y + 0.22, 11.8, 0.8, t, { font: "light", size: 26, lineH: 1.1 });
        });
        s.line(0.75, 6.15, 12.58, 6.15, { color: "rule", w: 1 });
        s.source("Tenan & Alejo, J Athl Train, 2024 · Rimer et al., Strength Cond J, 2024", { x: 4.6, y: 6.25, w: 7.98, align: "right", refs: ["tenan2024", "rimer2024"] });
      },
    },
    {
      role: "insight", time: 70,
      notes: `Here are three published readings of the same word, all from serious people.

In mechanics, a load is a force, measured in newtons. A group of sport scientists argued in 2022 that we borrow the word loosely.

In training science, load is what the session asked of the athlete and how the body responded: external and internal load.

And the IOC's consensus statement defines load broadly on purpose: training plus games, travel, a crowded calendar and psychological stress.

None of these is wrong. The trouble starts when one person means the first and another hears the third.`,
      build(s) {
        s.headline("Each field reads “load” its own way.", { x: 1.5, y: 1.2, w: 10.333, h: 0.75, size: 38, align: "center" });
        s.text(3.5, 2.05, 6.333, 1.5, "LOAD", { font: "condLight", size: 110, color: "accent", align: "center", lineH: 1.0, tracking: 6 });
        const cx = [2.55, 6.667, 10.78];
        const cols = [
          ["Mechanics", "A force, measured in newtons."],
          ["Training science", "What a session asked, and how the body answered."],
          ["IOC consensus", "Training plus games, travel and life stress."],
        ];
        cols.forEach(([lab, t], i) => {
          s.line(6.667, 3.62, cx[i], 4.15, { color: "rule", w: 1.25 });
          s.label(lab, { x: cx[i] - 1.85, y: 4.32, w: 3.7, align: "center", size: 15 });
          s.text(cx[i] - 1.85, 4.75, 3.7, 1.2, t, { font: "light", size: 22, align: "center", lineH: 1.15 });
        });
        s.line(4.6, 4.35, 4.6, 5.8, { color: "rule", w: 1 });
        s.line(8.733, 4.35, 8.733, 5.8, { color: "rule", w: 1 });
        s.source("Staunton et al. 2022 · Impellizzeri et al. 2019 · Soligard et al. 2016", { x: 1.5, y: 6.2, w: 10.333, align: "center", refs: ["staunton2022", "impellizzeri2019", "soligard2016"] });
      },
    },
    {
      role: "application", time: 60,
      notes: `The fix is simple and a little uncomfortable: say the thing you measured, not the label.

"His load is high" sounds informative and tells nobody what to do. "His sprint volume doubled this week, and he's sleeping five hours" tells the coach, the athletic trainer and the nutritionist exactly what changed. This example was written for the deck, but you've all heard the first version.

One more step if it helps: a one-page list of the ten words we share most, with what each unit means by them. It costs an hour of a meeting.`,
      build(s) {
        s.rect(0, 0, 4.6, 7.5, { fill: "soft" });
        s.headline("Say what you measured, not the label.", { x: 0.75, y: 1.3, w: 3.4, h: 3.2, size: 48 });
        s.label("Before", { x: 5.3, y: 1.45, w: 3 });
        s.text(5.3, 1.85, 7.28, 0.8, "“His load is high.”", { font: "light", size: 30, color: "muted", lineH: 1.1 });
        s.line(5.3, 3.0, 12.58, 3.0, { color: "rule", w: 1 });
        s.label("After", { x: 5.3, y: 3.3, w: 3, color: "accent" });
        s.text(5.3, 3.7, 7.28, 1.8, "“His sprint volume doubled this week, and he’s sleeping five hours.”", { font: "medium", size: 32, lineH: 1.12 });
        s.text(5.3, 5.75, 7.28, 0.4, "Example written for this deck.", { font: "light", size: 13, color: "muted" });
      },
    },
    {
      role: "takeaway", time: 50,
      notes: `The line to take away: define the word before you use it. Or skip the word and say the number.

Question for the room: which word do we use across units without ever defining it? Load is my guess. Others I hear: recovery, readiness, cleared, fatigued. Take two or three answers and write them down; that list is the start of the one-pager.`,
      build(s) {
        s.headline("Define the word before you use it.", { x: 1.2, y: 1.6, w: 10.933, h: 1.3, size: 64, align: "center" });
        s.line(6.167, 3.3, 7.167, 3.3, { color: "rule", w: 2 });
        s.text(2.2, 3.7, 8.933, 1.6, "Which word do we use across units without ever defining it?", { font: "medium", size: 32, color: "accent", align: "center", lineH: 1.15 });
      },
    },
  ],
};

