        s.text(4.35, y + h + 0.2, 4.55, 0.9, "Eat, drink, shower, decompress", { font: "light", size: 22, align: "center", lineH: 1.15 });
        s.line(4.35, y - 0.05, 4.35, y + h + 0.05, { color: "muted", w: 1 });
        s.line(8.9, y - 0.05, 8.9, y + h + 0.05, { color: "muted", w: 1 });
        s.text(0.75, 5.55, 9, 0.4, "A planning rule from our EAI proposal, not a tested number.", { font: "light", size: 16, color: "muted" });
        s.source("Why the gap: Wittbrodt & Millard-Stafford 2018 · ACSM 2007", { x: 0.75, y: 6.2, w: 9, refs: ["eai", "wittbrodt2018", "acsm2007"] });
      },
