# Export decks through PowerPoint: deck.pdf, png/slide1..5.png (QA renders) and thumb.png.
# Usage: pwsh -NoProfile -File scripts/export.ps1 [06 12 ...]   (no args = every deck)
param([Parameter(ValueFromRemainingArguments = $true)][string[]]$Decks)

$root = Join-Path $PSScriptRoot "..\decks" | Resolve-Path
$dirs = Get-ChildItem $root -Directory | Where-Object { $_.Name -match '^\d\d-' -and (Test-Path (Join-Path $_.FullName 'deck.pptx')) }
if ($Decks) {
  $want = @($Decks | ForEach-Object { $_ -split '[,\s]+' } | Where-Object { $_ } | ForEach-Object { $_.PadLeft(2, '0') })
  $dirs = @($dirs | Where-Object { $want -contains $_.Name.Substring(0, 2) })
}

# One PowerPoint automation at a time: parallel builders queue here.
$lock = New-Object System.Threading.Mutex($false, 'five-slides-pptx-export')
[void]$lock.WaitOne()
$app = New-Object -ComObject PowerPoint.Application
try {
  foreach ($d in $dirs) {
    $pptx = Join-Path $d.FullName 'deck.pptx'
    $pres = $app.Presentations.Open($pptx, $true, $false, $false)  # read-only, no window
    try {
      $pres.SaveAs((Join-Path $d.FullName 'deck.pdf'), 32)            # ppSaveAsPDF
      $png = Join-Path $d.FullName 'png'
      New-Item -ItemType Directory -Force $png | Out-Null
      for ($i = 1; $i -le $pres.Slides.Count; $i++) {
        $pres.Slides.Item($i).Export((Join-Path $png "slide$i.png"), 'PNG', 1600, 900)
      }
      $pres.Slides.Item(1).Export((Join-Path $d.FullName 'thumb.png'), 'PNG', 800, 450)
      Write-Output "ok   $($d.Name)"
    } finally { $pres.Close() }
  }
} finally {
  $app.Quit()
  [System.Runtime.Interopservices.Marshal]::ReleaseComObject($app) | Out-Null
  $lock.ReleaseMutex()
}
